INSERT INTO activity (id,project_id,node_id,event,summary,created_at,details)
SELECT 'migration_shared_graph_' || id,project_id,id,'work.migrated','Preserved earlier state: ' || status,strftime('%Y-%m-%dT%H:%M:%fZ','now'),json_object('originalStatus',status,'before',json_object('id',id,'projectId',project_id,'kind',kind,'title',title,'summary',summary,'body',body,'blocker',blocker,'outcome',outcome,'artifacts',json(artifacts),'createdAt',created_at,'updatedAt',updated_at,'status',status,'stopReason','','version',version),'after',json_object('id',id,'projectId',project_id,'kind',kind,'title',title,'summary',summary,'body',body,'blocker',blocker,'outcome',outcome,'artifacts',json(artifacts),'createdAt',created_at,'updatedAt',updated_at,'status',CASE status WHEN 'pending' THEN 'planned' WHEN 'active' THEN 'working' WHEN 'in_review' THEN 'working' WHEN 'succeeded' THEN 'done' ELSE 'stopped' END,'stopReason',CASE WHEN status IN ('failed','canceled') THEN COALESCE(NULLIF(blocker,''),NULLIF(outcome,''),'Work previously ' || status || '.') ELSE '' END,'version',version+1)) FROM nodes WHERE status IN ('pending','active','in_review','succeeded','failed','canceled');
--> statement-breakpoint
UPDATE nodes SET stop_reason=CASE WHEN status IN ('failed','canceled') THEN COALESCE(NULLIF(blocker,''),NULLIF(outcome,''),'Work previously ' || status || '.') ELSE '' END,status=CASE status WHEN 'pending' THEN 'planned' WHEN 'active' THEN 'working' WHEN 'in_review' THEN 'working' WHEN 'succeeded' THEN 'done' ELSE 'stopped' END,version=version+1 WHERE status IN ('pending','active','in_review','succeeded','failed','canceled');
